def _program_contains(program: Program, node_type: Type[object]) -> bool:
    """Recursively determine whether ``program`` includes ``node_type``."""

    seen: set[int] = set()

    def _visit(value: object) -> bool:
        if isinstance(value, node_type):
            return True
        if isinstance(value, (str, bytes, bytearray)):
            return False
        if isinstance(value, (list, tuple, set)):
            for item in value:
                if _visit(item):
                    return True
            return False
        if isinstance(value, dict):
            for item in value.values():
                if _visit(item):
                    return True
            return False
        if hasattr(value, "__dict__"):
            key = id(value)
            if key in seen:
                return False
            seen.add(key)
            for attr_value in value.__dict__.values():
                if _visit(attr_value):
                    return True
        return False

    return _visit(program)


def _collect_required_libraries(program: Program) -> List[str]:
    """Return PlatformIO libraries required by the transpiled program."""

    requirements: List[str] = []
    if _program_contains(program, ServoDecl):
        requirements.append("Servo")
    return requirements

def _format_lib_section(libraries: Iterable[str] | None) -> str:
    """Render a ``lib_deps`` section for ``platformio.ini`` if needed."""

    if not libraries:
        return ""

    unique: List[str] = []
    for entry in libraries:
        if not entry:
            continue
        if entry not in unique:
            unique.append(entry)

    if not unique:
        return ""

    lines = ["lib_deps ="]
    lines.extend(f"  {name}" for name in unique)
    return "\n".join(lines)

class ServoDecl:
    """Declare a hobby servo bound to ``pin`` with optional calibration."""

    name: str
    pin: Union[int, str] = 9
    min_angle: Union[float, int, str] = 0.0
    max_angle: Union[float, int, str] = 180.0
    min_pulse_us: Union[float, int, str] = 544.0
    max_pulse_us: Union[float, int, str] = 2400.0


@dataclass
class ServoWrite:
    """Command the servo to move to an angle in degrees."""

    name: str
    angle: Union[float, int, str]


@dataclass
class ServoWriteMicroseconds:
    """Command the servo using a pulse width in microseconds."""

    name: str
    pulse_us: Union[float, int, str]


